    "version": "v0.9",
    "updateDataModel": {
      "surfaceId": "sat-math-schedule",
      "value": {
        "week1_schedule": [
          {
            "day": "Monday",
            "focus": "Linear Equations",
            "topics": "Solving linear equations (one variable), word problems involving linear equations."
          },
          {
            "day": "Tuesday",
            "focus": "Systems of Equations",
            "topics": "Solving systems of linear equations (substitution, elimination, graphing), word problems."
          },
          {
            "day": "Wednesday",
            "focus": "Linear Inequalities",
            "topics": "Solving linear inequalities, graphing on a number line, systems of linear inequalities."
          },
          {
            "day": "Thursday",
            "focus": "Interpreting Linear Functions",
            "topics": "Understanding slope, intercepts, rate of change, and interpreting linear functions in context."
          },
          {
            "day": "Friday",
            "focus": "Functions Basics",
            "topics": "Function notation, evaluating functions, domain and range, basic linear function graphs."
          },
          {
            "day": "Saturday",
            "focus": "Week 1 Review & Practice",
            "topics": "Comprehensive review of Week 1 topics. Timed practice set on Algebra, analyze errors."
          }
        ],
        "week2_schedule": [
          {
            "day": "Monday",
            "focus": "Ratios, Proportions, Percentages",
            "topics": "Setting up and solving ratio, proportion, and percentage problems, including word problems."
          },
          {
            "day": "Tuesday",
            "focus": "Rates & Unit Conversions",
            "topics": "Solving problems involving rates, unit conversions, and proportional relationships (direct/inverse variation)."
          },
          {
            "day": "Wednesday",
            "focus": "Data Interpretation",
            "topics": "Reading and interpreting data from tables, charts, and graphs; calculating basic statistics."
          },
          {
            "day": "Thursday",
            "focus": "Statistics Concepts",
            "topics": "Mean, median, mode, range, and conceptual understanding of standard deviation."
          },
          {
            "day": "Friday",
            "focus": "Probability",
            "topics": "Basic probability concepts, simple and compound events, conditional probability."
          },
          {
            "day": "Saturday",
            "focus": "Week 2 Review & Practice",
            "topics": "Comprehensive review of Week 2 topics. Timed practice set on Data Analysis, analyze errors."
          }
        ],
        "week3_schedule": [
          {
            "day": "Monday",
            "focus": "Polynomials",
            "topics": "Operations with polynomials (addition, subtraction, multiplication), factoring simple quadratics."
          },
          {
            "day": "Tuesday",
            "focus": "Quadratic Equations",
            "topics": "Solving quadratic equations (factoring, quadratic formula, completing the square)."
          },
          {
            "day": "Wednesday",
            "focus": "Functions & Graphs",
            "topics": "Graphing parabolas, identifying roots/vertex, understanding function transformations."
          },
          {
            "day": "Thursday",
            "focus": "Exponential Functions & Radicals",
            "topics": "Exponential growth/decay, properties of exponents, simplifying and operating with radicals."
          },
          {
            "day": "Friday",
            "focus": "Rational Expressions & Equations",
            "topics": "Simplifying rational expressions, solving basic rational equations."
          },
          {
            "day": "Saturday",
            "focus": "Week 3 Review & Practice",
            "topics": "Comprehensive review of Week 3 topics. Timed practice set on Advanced Math, analyze errors."
          }
        ],
        "week4_schedule": [
          {
            "day": "Monday",
            "focus": "Targeted Practice: Algebra",
            "topics": "Focused practice on identified weak areas from Week 1 & 2 Algebra topics."
          },
          {
            "day": "Tuesday",
            "focus": "Targeted Practice: Data Analysis",
            "topics": "Focused practice on identified weak areas from Week 2 Data Analysis topics."
          },
          {
            "day": "Wednesday",
            "focus": "Targeted Practice: Advanced Math",
            "topics": "Focused practice on identified weak areas from Week 3 Advanced Math topics."
          },
          {
            "day": "Thursday",
            "focus": "Full SAT Math Practice Test",
            "topics": "Take a full, timed SAT Math section practice test (70 minutes)."
          },
          {
            "day": "Friday",
            "focus": "Practice Test Review",
            "topics": "Thoroughly review Thursday's practice test. Understand every incorrect answer, revisit relevant topics."
          },
          {
            "day": "Saturday",
            "focus": "Second Full SAT Math Practice Test",
            "topics": "Take another full, timed SAT Math section practice test. Final review of common mistakes and strategies."
          }
        ]
      }
    }
  },
