                    {
                      "id": "tip_1",
                      "type": "Text",
                      "properties": {
                        "text": "Use official College Board SAT practice tests for the most accurate preparation."
                      }
                    },
                    {
                      "id": "tip_2",
                      "type": "Text",
                      "properties": {
                        "text": "Keep an error log: For every question you get wrong, write down the topic, why you got it wrong, and the correct approach."
                      }
                    },
                    {
                      "id": "tip_3",
                      "type": "Text",
                      "properties": {
                        "text": "Don't just practice; understand. Focus on the underlying concepts, not just memorizing formulas."
                      }
                    },
                    {
                      "id": "tip_4",
                      "type": "Text",
